/**
 * The local database. Every read in the app comes from here, so a screen
 * renders on the first frame whether or not the network is up.
 *
 * The tables mirror the sync entities the API knows about (word, progress,
 * settings, notebook, confusion), which is what lets a pulled change be
 * applied and a local edit be pushed without translation.
 */
import Dexie, { type EntityTable } from 'dexie';
import type { Progress, Settings, Streak, Word, LanguageCode } from '@lexpad/core';
import type {
  ApiBillingState,
  ApiForm,
  ApiNudgeView,
  ApiReferralView,
  ApiSrsState,
  ApiSrsStats,
  ApiSurfaceStatus,
} from '@/api/types.js';
import { forgetReads } from '@/lib/readMemory.js';
import type { DesktopRelease } from '@/lib/platform/types.js';

/**
 * A word as stored locally: the domain shape without the learning state,
 * which lives in its own table because it changes far more often and syncs
 * as its own entity.
 *
 * The local shapes come from `@lexpad/core`, not from the generated API
 * types. The generated types render the spec's `allOf` schemas as
 * intersections whose optional halves make required fields read as possibly
 * undefined; mapping happens once, at the network boundary in `sync/`.
 */
export type StoredWord = Omit<Word, 'progress'>;

/** A word's learning state, keyed by word id. */
export interface StoredProgress extends Progress {
  wordId: string;
}

/** A notebook as stored locally. */
export interface StoredNotebook {
  id: string;
  title: string;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  isDefault: boolean;
  sortOrder: number;
  role: string;
  wordCount: number;
  createdAt: string;
  updatedAt: string;
}

/**
 * This learner's saved schedule settings for one notebook (SRS v2), keyed by
 * the notebook id. Only saved settings live here; a notebook without a row
 * runs on the defaults the server announces (meta `srs`). It comes from the
 * snapshot and the `schedule` sync entity, and is changed only through
 * `PUT /notebooks/{id}/schedule`, never the outbox.
 */
export interface StoredSchedule {
  notebookId: string;
  scheduler: 'boxes' | 'smart';
  retention: number;
  afterMiss: 'restart' | 'back2';
  extraPractice: 'keep' | 'moves';
  /** 0 is no limit. */
  reviewCap: number;
  leechThreshold: number;
  maxInterval: number;
  params?: { w: number[]; source: 'default' | 'tuned'; tunedAt?: string; reviews?: number };
  tuning: boolean;
  updatedAt?: string;
}

/** A confusion pair count, keyed by the two ids joined with a dash. */
export interface StoredConfusion {
  key: string;
  wordA: string;
  wordB: string;
  count: number;
}

/** One day's review totals. */
export interface StoredDayStat {
  day: number;
  reviewed: number;
  correct: number;
  newWords: number;
}

/**
 * Everything that is one value per account: the signed-in user, the sync
 * cursor, the settings and the streak. Keyed so Dexie can hold them in one
 * table without a schema change every time we add one.
 */
export interface StoredMeta {
  key: keyof MetaShape;
  value: unknown;
}

/**
 * The kinds of change the outbox carries. The first five are sync entities
 * and go to `POST /sync/push`; `review` is a graded card and goes to
 * `POST /reviews`, which keeps the event itself rather than only its effect
 * on the learning state; `undo` takes back one review the server already
 * has, by its client id, through `POST /progress/{wordId}` (`undoReview`);
 * `feedback` is a note from Settings → Send feedback that could not go at
 * once, sent to `POST /me/feedback` with its client id as the key.
 * All are idempotent, and all are sent in the order they were made.
 */
export type OutboxEntity =
  'word' | 'progress' | 'settings' | 'notebook' | 'confusion' | 'review' | 'undo' | 'feedback';

/** What an `undo` item carries. */
export interface UndoPayload {
  /** The client id of the review to take back. */
  reviewClientId: string;
  /** When the learner tapped Undo, on this device's clock. */
  clientTs: string;
  /**
   * The updatedAt the word was put back to locally. A grade made after the
   * undo carries it as its token; once the server answers, those grades
   * carry the server's stamp instead (see the worker).
   */
  restoredUpdatedAt: string;
}

/** What the user did while offline, waiting to be pushed. */
export interface OutboxItem {
  /** Auto-incremented, and also the push order. */
  seq?: number;
  /** The client-generated id that makes the push idempotent. */
  clientId: string;
  entity: OutboxEntity;
  entityId: string;
  op: 'upsert' | 'delete';
  payload?: unknown;
  clientTs: string;
  /** The sync cursor the client held when it made this change. */
  baseCursor?: string;
  attempts: number;
  lastError?: string;
  /**
   * Set aside after repeated failures the item itself may be causing. A
   * parked change is never deleted: the learner's data stays local and can
   * be retried from Settings.
   */
  parked?: boolean;
  /**
   * Set on a review just before its first send. A review that was never
   * sent can be dropped by Undo without a word to the server; one that was
   * may have arrived, so Undo also asks the server to take it back.
   */
  attempted?: boolean;
}

/**
 * What a model wrote into a word that keeps another source (features/ai,
 * `enrichWord`): "Fill with AI" pouring meanings into imported words, and
 * "Improve with AI" adding to a word the learner typed. Such a word is not
 * `source: 'ai'`, yet the store policies on generated content (Google Play,
 * Microsoft Store 11.16, Apple) want everything the model wrote reportable
 * where it is shown; this is how the word page knows which senses those are.
 *
 * Kept on this device only: the sync contract has no per-meaning provenance
 * and the server rewrites neither `source` nor `aiModel` on an update, so a
 * field on the word row would be lost on the next pull. A row of its own
 * survives pulls untouched. A sense is matched by its text, so one the
 * learner rewrites is theirs and is no longer flagged.
 */
export interface StoredAiMark {
  wordId: string;
  /** The senses the model wrote, by `senseKey` of the meaning, with the job that wrote each. */
  meanings: { key: string; jobId?: string }[];
  /**
   * The model also added something that is not a sense of its own: an
   * example lent to a learner's sense, phrases, a note, a level.
   */
  other: boolean;
  /** The latest job that wrote into the word, when known. */
  jobId?: string;
  /** When it last wrote (ISO). */
  at: string;
}

/** The typed Dexie instance. */
export class LexpadDb extends Dexie {
  words!: EntityTable<StoredWord, 'id'>;
  progress!: EntityTable<StoredProgress, 'wordId'>;
  notebooks!: EntityTable<StoredNotebook, 'id'>;
  confusions!: EntityTable<StoredConfusion, 'key'>;
  dayStats!: EntityTable<StoredDayStat, 'day'>;
  meta!: EntityTable<StoredMeta, 'key'>;
  outbox!: EntityTable<OutboxItem, 'seq'>;
  schedules!: EntityTable<StoredSchedule, 'notebookId'>;
  aiMarks!: EntityTable<StoredAiMark, 'wordId'>;

  constructor(name = 'lexpad') {
    super(name);
    this.version(1).stores({
      // Indexes are the ones the screens actually query on.
      words: 'id, notebookId, position, createdAt, headword',
      progress: 'wordId, dueDay, box, [retired+dueDay]',
      notebooks: 'id, sortOrder',
      confusions: 'key, count',
      dayStats: 'day',
      meta: 'key',
      outbox: '++seq, clientId, entity, [entity+entityId]',
    });
    // SRS v2: each notebook's schedule settings. Nothing is rewritten; the
    // progress table keeps its indexes and gains only unindexed fields.
    this.version(2).stores({ schedules: 'notebookId' });
    // What a model wrote into a word of another source (StoredAiMark).
    this.version(3).stores({ aiMarks: 'wordId' });
  }
}

/** The database this app instance uses. */
export const db = new LexpadDb();

/** Drops every local table, and every screen's remembered read of them. Used by sign-out and by "reset". */
export async function clearLocalData(database: LexpadDb = db): Promise<void> {
  await database.transaction(
    'rw',
    [
      database.words,
      database.progress,
      database.notebooks,
      database.confusions,
      database.dayStats,
      database.meta,
      database.outbox,
      database.schedules,
      database.aiMarks,
    ],
    async () => {
      await Promise.all([
        database.words.clear(),
        database.progress.clear(),
        database.notebooks.clear(),
        database.confusions.clear(),
        database.dayStats.clear(),
        database.meta.clear(),
        database.outbox.clear(),
        database.schedules.clear(),
        database.aiMarks.clear(),
      ]);
    },
  );
  // A screen's remembered read is a copy of what was just cleared.
  forgetReads();
}

/** Typed meta accessors, so callers do not repeat the cast. */
/** One notification in the bell's copy of the inbox. Instants are UTC ISO strings ending in Z. */
export interface InboxNotification {
  id: string;
  /** campaign, gift_ai_cards, gift_pro or comeback. */
  kind: string;
  title: string;
  body: string;
  /** Kept for copies written by older builds: an in-app path; absent opens Today. */
  link?: string;
  /**
   * The in-app path a tap opens (the server's `tapPath`): a screen, a form
   * (/forms/{id}) or this message's own page (/notifications/{id}). Absent in
   * copies written before it existed, which then use `link`. Checked with
   * `inAppPath` before it is followed.
   */
  tapPath?: string;
  /** The message's button: an in-app form or an external link. */
  action?: InboxAction;
  createdAt: string;
  readAt?: string;
}

/** A notification's button, as the server sent it (AppNotification.action). */
export interface InboxAction {
  type: 'form' | 'url';
  /** The operator's words for the button; absent means the app's own. */
  label?: string;
  /** url only; absent when the server no longer allows its host. Checked again before use. */
  url?: string;
  /** form only. */
  formId?: string;
  /** form only: this account has answered it. */
  answered?: boolean;
  /** form only: it still takes answers. */
  open?: boolean;
}

/**
 * Answers to a form not sent yet, kept on this device until they are
 * (features/forms). `form` is the copy they were given against, so a form
 * opened again offline still shows its questions with the answers in place.
 */
export interface FormDraft {
  /** Question id to answer: an option id, option ids, a rating, or text. */
  answers: Record<string, string | string[] | number>;
  /** The key the last send went with; a send of the same answers repeats it. */
  idempotencyKey?: string;
  form?: ApiForm;
  /** When it was last changed, ISO. */
  savedAt: string;
}

/** See MetaShape.swipe. */
export interface StoredSwipe {
  /** Settings → Practice → "Swipe to answer" was turned off. */
  off: boolean;
  /** Sessions in which the coach's demo on a turned card played. */
  backDemos: number;
  /** Sessions in which the coach's line on a card's front showed. */
  frontLines: number;
  /** A card was graded by a swipe on this device, ever. */
  swiped: boolean;
  /** A card was graded by a swipe from its front, ever. */
  swipedFront: boolean;
}

/**
 * What this device remembers about the new learner's tips (meta `tips`,
 * read and written by features/learn). Tip ids are the keys of `seen`.
 */
export interface StoredTips {
  /** The local day each tip was first shown. Shown once counts as put away. */
  seen: Partial<Record<string, number>>;
  /** The day `today` counts for. */
  day: number;
  /** New tips shown on `day`. */
  today: number;
  /** "Show tips" was turned off in Settings → Practice. */
  off: boolean;
  /** Settled once: this device met tips before it had any practice history. */
  beginner: boolean;
  /** The local day tips were first settled here: the learner's first day. */
  firstDay: number;
  /** Practice sessions started since then. */
  sessions: number;
  /** Session summaries seen since then. */
  summaries: number;
  /** The last practice day before the break whose welcome-back line was shown. */
  comeback: number | null;
}

/**
 * What this device remembers about the Pro trial's few words on Today (meta
 * `trialNotes`, features/billing/trial.ts). Each moment is shown once: a
 * card or line that has been put on screen is not put there again in a later
 * visit, and one put away is gone. Dates are the server's own `endsAt` and
 * `endedAt`, so a second trial (an opt-in after the first) is a new moment.
 */
/**
 * The account's last plan as the server answered it (features/billing/
 * planSnapshot.ts), kept only so Today can draw the trial's chip and moments
 * on a cold start, offline-first. It is never used to sell, to lock a
 * feature or to decide that anybody has paid: those ask the server.
 */
export interface StoredPlanSnapshot {
  /** The account it belongs to; another account's snapshot is never used. */
  account: string;
  /** When the server answered. */
  at: string;
  state: ApiBillingState;
}

/**
 * What this device remembers about campaigns (offer presentation spec §3):
 * when the Today banner was put away for each campaign, whether it came
 * back for its last day, and which campaigns opened full screen, when.
 * Per device, like the trial's notes; the server keeps the funnel.
 */
export interface StoredOfferNotes {
  /** Campaign id → the instant its banner may show again after "Not now". */
  bannerSnoozedUntil?: Record<string, string>;
  /** Campaigns whose banner came back once in its last 24 hours. */
  bannerReturned?: string[];
  /** Campaigns whose banner "Don't remind me" or a purchase ended for good. */
  bannerDone?: string[];
  /** Campaigns that opened full screen on this device (once per campaign). */
  fullscreenShown?: string[];
  /** When a campaign last opened full screen here (at most one a fortnight). */
  fullscreenAt?: string;
  /** When a real milestone (a burst or a takeover) was last celebrated here. */
  milestoneAt?: string;
  /** Campaigns whose after-milestone card was shown here (once per campaign). */
  afterMilestoneShown?: string[];
  /** Which celebration the last milestone was (its id) and its number, for the moment card. */
  milestoneId?: string;
  milestoneCount?: number;
  /** Milestone kinds the moment card has spoken of here (once per kind). */
  momentMilestoneKinds?: string[];
  /** When the moment card after a milestone was last shown here (one a month). */
  momentMilestoneAt?: string;
  /** The local day the AI-limit line last mentioned the moment price (once a day). */
  momentInlineDay?: number;
  /** Campaign id → the local day its banner was last put on screen (moment offer: once a day). */
  bannerDay?: Record<string, number>;
}

export interface StoredTrialNotes {
  /** When this device first saw a running trial: the start, if nothing better is known. */
  firstSeen?: string;
  /** The midway card ("You have Pro until…") was put on screen. */
  midwaySeen?: boolean;
  /** …and was answered (its button or Not now). */
  midwayDone?: boolean;
  /** "Meet Lex" (trial-offers design §2.3, day 2) was put on screen, and answered. */
  meetLexSeen?: boolean;
  meetLexDone?: boolean;
  /** "A week of Pro" (day 7) was put on screen, and answered. */
  weekSeen?: boolean;
  weekDone?: boolean;
  /** "Not now" was tapped on a trial card: the next offer card is not shown. */
  notNow?: boolean;
  /** The one-time "Part of your Pro trial." line beside a Pro mark was shown. */
  markLineSeen?: boolean;
  /** The trial (by `endsAt`) whose "ends on" line was shown in the hero. */
  endingSeen?: string;
  /** The ended trial (by `endedAt`) whose end card was put on screen. */
  endSeen?: string;
  /** …and answered. */
  endDone?: string;
  /** The ended trial (by `endedAt`) whose full trial-end screen was shown. */
  endScreen?: string;
  /** The running trial (by `endsAt`) whose last-day screen was shown. */
  lastDayScreen?: string;
}

/**
 * What this device remembers about celebrations (meta `celebrate`, read and
 * written by features/celebrate/state.ts). Which moments the account has
 * had lives on the server (`/me/celebrations`); this is the device's copy
 * of those keys, the ones it spent and has not claimed yet, and its own
 * switch. Null until the baseline is settled.
 */
export interface StoredCelebrate {
  /** The local day and instant the baseline was taken on this device. */
  settledDay: number;
  settledAt: string;
  /** The account was in its first hours when this device settled: its trial is new. */
  youngAtSettle: boolean;
  /** Keys spent: shown here, passed over, set by the baseline, or claimed by another device. */
  spent: string[];
  /** Keys spent here that the server has not been told about yet (offline). */
  pending: string[];
  /** Words the leech prompt flagged on this device, for "stuck this time". */
  flagged: string[];
  /** A words milestone a save reached today, waiting for the notebook's toast or Today. */
  pendingWords: { value: number; day: number } | null;
  /** The busiest day before `asOf`, and how many days had practice before it, kept as days pass. */
  busy: { asOf: number; best: number; days: number } | null;
  /** The streak the chip on Today last drew, so it lifts only when it grew. */
  chip: number;
  /** Settings → Practice → Celebrations is off on this device. */
  off: boolean;
  /** When the server's keys were last read (epoch ms). */
  fetchedAt: number | null;
}

/**
 * The account's AI card allowance, as the server reported it (GET
 * /billing/state, or the body of a 429). Every field is optional: an older
 * server sends none of them, and the screens then say nothing numeric.
 */
export interface StoredAiAllowance {
  dailyLimit?: number;
  dailyUsed?: number;
  monthlyLimit?: number;
  monthlyUsed?: number;
  /** ISO instant the daily allowance renews. */
  resetsDailyAt?: string;
  /** ISO instant the monthly allowance renews. */
  resetsMonthlyAt?: string;
  /** When this device heard it, so a stale count is never shown as today's. */
  seenAt: string;
}

export interface MetaShape {
  user: {
    id: string;
    email: string;
    displayName: string;
    timezone: string;
    locale: string;
    // Added later; rows written by older builds lack them.
    emailVerified?: boolean;
    /** The address is Apple's relay ("Hide My Email"); see features/auth/hiddenEmail.ts. */
    emailHidden?: boolean;
    /** "News, offers and new features"; absent (older builds) reads as on. */
    emailNews?: boolean;
    marketingOptIn?: boolean;
    providers?: readonly string[];
    createdAt?: string;
  } | null;
  cursor: string;
  settings: Settings | null;
  streak: Streak;
  activeNotebook: string | null;
  lastSyncAt: string | null;
  onboarded: boolean;
  /** Epoch milliseconds until which the confirm-e-mail banner stays hidden. */
  verifySnoozedUntil: number | null;
  /** The last read of the site's version file, for sideloaded Android builds. */
  updateCheck: { at: number; version: string; url: string } | null;
  /**
   * The last read of the site's version file inside the desktop app: its
   * desktop section, and this computer and copy as the core described them.
   */
  desktopRelease: { at: number; release: DesktopRelease } | null;
  /** A newer version the person chose not to be told about again. */
  updateDismissed: string | null;
  /** ISO instant until which AI cards are resting after the server refused a request. */
  aiPausedUntil: string | null;
  /**
   * Which allowance the refusal behind `aiPausedUntil` was about, when the
   * server said: `day` or `month`. Null when it did not say, and then the
   * screens make no claim about when it renews beyond the instant itself.
   */
  aiPauseKind: 'day' | 'month' | null;
  /** The account's AI card allowance as the server last reported it (features/ai/quota.ts). */
  aiAllowance: StoredAiAllowance | null;
  /**
   * AI jobs "Fill with AI" started and has not yet poured into the words
   * (features/ai/fill.ts), so a closed tab or a second tap watches the job
   * already paid for instead of asking again for the same words.
   */
  fillJobs: StoredFillJob[];
  /**
   * Words "Fill with AI" asked for and the AI declined (not a word it knows,
   * or a card it could not write twice), by notebook and normalised headword
   * (features/ai/fill.ts). The card stops offering the AI for them and asks
   * for the learner's own meaning, an edit or a delete instead. Editing the
   * headword or giving it a meaning lets it go. Kept on this device only.
   */
  fillDeclined: StoredFillDecline[];
  /**
   * Whether the browser extension has ever been connected to this account.
   * A milestone rather than a state: the extension marks its words like any
   * other, so the only trace it leaves is a session, and that is a network
   * read. Once seen it stays seen.
   */
  extensionSeen: boolean;
  /**
   * Whether the getting-started list was offered here, and whether finishing
   * it has been celebrated. Decided once, on the first launch that looks:
   * an account that already has words and a practice history is not new, so
   * it is never celebrated for a list it did not need. Since 22 Oct 2026 the
   * list lives in Settings → Help & about and `offered` is no longer read;
   * it keeps its place so stored values keep their shape.
   */
  getStarted: { offered: boolean; celebrated: boolean } | null;
  /** Whether "Not now" was chosen on Today's offer to turn the reminder on. */
  reminderOfferDismissed: boolean;
  /**
   * Whether the first session's summary has offered the daily reminder on
   * this device (features/session/FirstReminder.tsx). Asked once, ever: it
   * moved there from onboarding on 2026-10-09.
   */
  reminderAsked: boolean;
  /**
   * What the onboarding questions answered on this device (onboarding v2,
   * spec §10): why the learner learns, where they meet words (in the order
   * they ticked them; Today's "More ways to bring in words" lists those
   * first) and the minutes a day the plan was made for. Since 2026-10-22 up
   * to three reasons, in the order they were picked (it was one,
   * `onboardingGoal`, which nothing read).
   */
  onboardingGoals: readonly ('exam' | 'work' | 'move' | 'read' | 'travel' | 'me')[];
  wordSources: readonly ('books' | 'web' | 'video' | 'class' | 'ai')[];
  planMinutes: number | null;
  /**
   * The same answers waiting to be sent to the account (PUT
   * /me/onboarding, features/intro/sendAnswers.ts): written by the first
   * card, sent once, and cleared once the server has them or refused them.
   * `at` is when they were answered, so a server that never takes them is
   * not asked for ever.
   */
  onboardingAnswers: {
    goals: readonly ('exam' | 'work' | 'move' | 'read' | 'travel' | 'me')[];
    sources: readonly ('books' | 'web' | 'video' | 'class' | 'ai')[];
    at: string;
  } | null;
  /**
   * The goal picked in the introduction (sales plan G, 23 Oct 2026): a
   * number of words by a local day ("YYYY-MM-DD"), and when it was set.
   * Written by the first card; on this device only until the server's
   * onboarding answers have a field for it. Nothing shows it yet.
   */
  learningGoal: { words: number; by: string; at: string } | null;
  /**
   * The web reminder offer (features/reminder, marketer's F3, 2026-10-18):
   * the local day the first practice day's summary showed it in this
   * browser, whether "Not now" was pressed (here or on Today), and the day
   * Today's one later line showed. Once per device, so it lives here and not
   * on the server.
   */
  webReminder: { offeredDay: number | null; notNow: boolean; lineDay: number | null };
  /**
   * Whether this install's last registration gave the server a push token.
   * While it did, the server sends the come-back notifications and the local
   * plan leaves them out, so nobody hears the same thing twice; without one
   * (no Google services, Firebase blocked, notifications refused) the phone
   * keeps sending its own, which work offline.
   */
  pushReceives: boolean;
  /**
   * The newest page of the account's notifications, for the bell on Today
   * (features/inbox). A copy of what the server holds, kept so the bell
   * draws from local data on the first frame; `unread` is the server's count
   * for the whole inbox, lowered here as things are marked read.
   */
  inbox: { notifications: InboxNotification[]; unread: number } | null;
  /** Answers to forms not sent yet, by form id (features/forms/draft.ts). */
  formDrafts: Record<string, FormDraft>;
  /**
   * The one-time card that introduces Smart on the schedule page (SRS v2
   * phase C) was put away on this device.
   */
  smartIntroSeen: boolean;
  /**
   * The one-time card on Today inviting a learner with some history to try
   * Smart (SRS v2) was answered on this device, by "See how it works" or
   * "Not now". Either way it is never shown again.
   */
  smartInviteSeen: boolean;
  /**
   * Today's line offering a daily review limit after a break (SRS v2) was
   * tapped or put away: the last day practised before that break, so the
   * next break may offer it again and this one never does twice.
   */
  capOfferDismissed: number | null;
  /**
   * How the notebook was last looked at on this device (features/notebook/viewMemory.ts).
   * Loosely typed on purpose: a value written by another build is checked on the way in.
   * Older builds also wrote the filter, level and kind; they are ignored now.
   */
  notebookView: {
    filter?: string;
    order: string;
    showMeanings?: boolean;
    showExamples?: boolean;
    level?: string;
    kind?: string;
  } | null;
  /**
   * The last answer to GET /me/surfaces ("Lexpad everywhere"), with when it
   * was read, so the hub draws on the first frame and offline says "as of".
   */
  surfaces: { at: string; list: ApiSurfaceStatus[] } | null;
  /** The last answer to GET or PUT /me/nudges: the cards' rules and history. */
  nudges: { at: string; view: ApiNudgeView } | null;
  /**
   * This app session (features/everywhere/session.ts): the app opened after
   * the server's sessionGapMinutes away starts a new one. One card a session.
   */
  appSession: { id: string; lastActiveAt: number } | null;
  /** How many times "Paste a text" or "Read a text" added words on this device. */
  pasteUses: number;
  /**
   * The "More ways to bring in words" card (features/getstarted/WaysIn) was
   * put away. Kept with this account's local data, which goes on sign-out;
   * the card also stops by itself once the notebook has grown.
   */
  waysInDismissed: boolean;
  /**
   * The parts of Today this device has shown (features/today/parts.ts), so a
   * part that has just appeared gets a "New" mark once. Null until Today first
   * draws its parts: that first drawing is the baseline, never marked.
   */
  todayParts: readonly ('latest' | 'week' | 'progress' | 'focused' | 'audio' | 'reading' | 'places')[] | null;
  /**
   * The last answer to GET /me/srs, with when it was read: which SRS v2
   * features this account and client may use. Null until it is first read;
   * `state` is null when the server has no such endpoint (404). Both mean
   * today's schedule and no SRS v2 screens.
   */
  srs: { at: string; state: ApiSrsState | null } | null;
  /**
   * The last answer to GET /me/srs/stats (SRS v2 phase D): "Remembered when
   * due" per notebook and what personal tuning last found, with when it was
   * read, so Progress and the schedule page draw it on the first frame and
   * say "as of" offline. Null until it is first read.
   */
  srsStats: { at: string; stats: ApiSrsStats } | null;
  /**
   * The practice modes on this device (SRS v2 phase E): whether the games
   * run without a clock (an accessibility choice), and the best Speed round
   * per notebook id. Kept here, not synced: a best score is this device's.
   */
  modes: { noTimer: boolean; speedBest: Record<string, number> } | null;
  /**
   * The new learner's tips on this device (features/learn): which were shown,
   * how many today, "Show tips", and whether this device met them as a
   * beginner. Null until settled, which happens only while the feature is on.
   * Per device on purpose: a tip seen once more on a second device is harmless,
   * and it keeps Today rendering from IndexedDB with no request.
   */
  tips: StoredTips | null;
  /**
   * Whether "More options" was left open on the schedule page and on
   * Settings → Practice, so it opens the same way next time on this device.
   */
  moreOptions: { schedule: boolean; practice: boolean } | null;
  /** The Pro trial's moments on Today, shown once each (features/billing/trial.ts). */
  trialNotes: StoredTrialNotes;
  /** Campaign banners and full-screen offers on this device (features/billing/campaign.ts). */
  offerNotes: StoredOfferNotes;
  /** Campaign pictures this device prefetched, by address, with when they may go. */
  campaignAssets: Record<string, string>;
  /** The last plan, for Today's trial chip and moments on a cold start. */
  planSnapshot: StoredPlanSnapshot | null;
  /** Celebrations on this device (features/celebrate); null until settled. */
  celebrate: StoredCelebrate | null;
  /**
   * Settings → Practice → "After an answer" on this device
   * (features/session/pace.ts). Null until chosen, which reads as the
   * default: wait for Next after a mistake.
   */
  afterAnswer: string | null;
  /**
   * Swipe to answer on this device (features/session/swipe): the Settings
   * switch and how far the swipe coach has got. Null until first written,
   * which reads as on with nothing taught yet. Never synced, like
   * `afterAnswer`: it is about how practice feels on this screen.
   */
  swipe: StoredSwipe | null;
  /**
   * Invite friends (features/invite): the last answer to GET /me/referral
   * with when it was read, so Settings draws it at once and Today knows the
   * programme is on without asking; the local day of the last good moment
   * (a 7-day streak or the first mastered word) shown on this device; and
   * when Today last offered the card. Null until first written.
   */
  invite: StoredInvite | null;
}

/** See MetaShape.fillJobs. */
export interface StoredFillJob {
  id: string;
  notebookId: string;
  /** The headwords sent, so another run leaves them to this job. */
  words: string[];
  /** When it was asked for (ISO), so one the server has long forgotten is let go. */
  at: string;
}

/** See MetaShape.fillDeclined. */
export interface StoredFillDecline {
  notebookId: string;
  /** The headword as `normalizeHeadword` has it. */
  key: string;
  /** When the AI declined it (ISO). */
  at: string;
}

/** See MetaShape.invite. */
export interface StoredInvite {
  view: ApiReferralView | null;
  at: string | null;
  momentDay: number | null;
  shownAt: number | null;
  /** The words moment (features/invite/state.ts) has been noted on this device. */
  wordsMoment?: boolean;
}

