/**
 * What a screen last read from the local database, kept in memory so a
 * return to it draws at once.
 *
 * Tester feedback, 2026-10-09: switching tabs, or coming back from a word,
 * the notebook showed "Your words start here" for half a second before its
 * words appeared, and Today showed an empty account's hero. Every visit
 * mounts the screen again, and its live query starts from nothing until
 * IndexedDB answers — with three thousand words that is a few hundred
 * milliseconds on a phone. With this, a screen drawn once in this run of
 * the app draws its last read on the first frame and the live query
 * refreshes it in place a moment later (stale while revalidate).
 *
 * Three rules keep a remembered read from ever showing the wrong thing:
 *
 * - **Memory only, never stored.** It is a moment-ago copy of this
 *   device's own database, gone on a reload. A cold start still reads
 *   before it draws.
 * - **One view at a time.** Each read says which notebooks it was of
 *   (`scope`); the newest read anywhere sets the scope, and a remembered
 *   read of another scope is not handed back. So switching notebooks on
 *   Today never lets the notebook screen draw the previous notebook's words.
 * - **Gone with the data.** `clearLocalData` (sign-out, another account
 *   signing in, Reset) forgets every read, so nobody ever sees the last
 *   account's words.
 */

/**
 * How many reads one screen keeps. A key is `<screen>:<view>`, and a
 * screen keeps one read per view (the notebook's filter, order and
 * search); a big notebook's read holds every word, so the oldest view goes
 * first. Three covers going back and forth between a search, a filter and
 * the whole list; a size, not data.
 */
export const READS_PER_SCREEN = 3;

interface Remembered {
  value: unknown;
  /** Undefined for a read that is not of particular notebooks (the account's switches). */
  scope: string | undefined;
}

const reads = new Map<string, Remembered>();
let currentScope: string | undefined;

/**
 * Keeps a read under its key, as the newest one. A read of particular
 * notebooks makes its scope the current one.
 */
export function rememberRead(key: string, value: unknown, scope?: string): void {
  reads.delete(key);
  reads.set(key, { value, scope });
  if (scope !== undefined) currentScope = scope;
  const screen = screenOf(key);
  const same = [...reads.keys()].filter((one) => screenOf(one) === screen);
  // Oldest first, since a key is moved to the end each time it is kept.
  for (const old of same.slice(0, Math.max(0, same.length - READS_PER_SCREEN))) reads.delete(old);
}

function screenOf(key: string): string {
  const colon = key.indexOf(':');
  return colon === -1 ? key : key.slice(0, colon);
}

/** The last read under this key, while it is of the notebooks now in view. */
export function recallRead(key: string): unknown {
  const entry = reads.get(key);
  if (entry === undefined) return undefined;
  if (entry.scope !== undefined && entry.scope !== currentScope) return undefined;
  return entry.value;
}

/** Forgets every read: the data they came from is gone. */
export function forgetReads(): void {
  reads.clear();
  currentScope = undefined;
}

/**
 * The scope a read of these notebooks belongs to: every notebook, or the
 * one being shown. Screens that read the same notebooks must agree on it.
 */
export function readScope(notebookId: string | undefined, across: boolean): string {
  if (across) return '*';
  return notebookId ?? '';
}
